// Input: items[0].json = your original array

const input = items[0].json;

// If input itself is an array (like your example)
const dataArray = Array.isArray(input) ? input : [input];

const results = dataArray.map(entry => {
  const data = entry["Existing Topics (and descriptions)"];

  const Topic = entry["Original Topic"];

  const Description = entry["Original Description"];

  const existingNewsletter = entry["Existing Newsletter"];

  const userInput = entry["User input/ Suggested Changes"];

  // Defensive check
  if (!data) return { json: { Topic: null, Description: null, existingNewsletter: null } };


  return {
    json: {
      Topic, 
      Description, 
      existingNewsletter,
      Feedback: userInput,
      recipient: "aryaniyappan2006@gmail.com"
    }
  };
});

return results;
